 for(const name of ['vUv','v_uv','isf_FragNormCoord'])if(!new RegExp('\\bin\\s+vec2\\s+'+name+'\\b').test(source))header.push('in vec2 '+name+';');
 if(s.format==='gl-transition')header.push('uniform float progress;','uniform float ratio;','uniform sampler2D motiveliumFrom;','uniform sampler2D motiveliumTo;','vec4 getFromColor(vec2 uv){return texture(motiveliumFrom,clamp(uv,vec2(0.),vec2(1.)));}','vec4 getToColor(vec2 uv){return texture(motiveliumTo,clamp(uv,vec2(0.),vec2(1.)));}');
 if(s.format==='isf'){header.push('uniform vec2 RENDERSIZE;','uniform float TIME;','uniform float TIMEDELTA;','uniform int FRAMEINDEX;','uniform int PASSINDEX;','uniform vec4 DATE;');for(const i of s.inputs)header.push('uniform '+i.type+' '+i.name+';');header.push('#define IMG_NORM_PIXEL(img,coord) texture(img,coord)','#define IMG_PIXEL(img,coord) texture(img,(coord)/RENDERSIZE)','#define IMG_THIS_PIXEL(img) texture(img,isf_FragNormCoord)','#define IMG_THIS_NORM_PIXEL(img) texture(img,isf_FragNormCoord)','#define IMG_SIZE(img) RENDERSIZE');}
