import type {Project} from '../../domain/schema.ts';import type {FrameState} from '../../render/evaluate.ts';import {layerQuad} from '../../domain/layers.ts';
export function drawLayerOverlay(canvas:HTMLCanvasElement,project:Project,state:FrameState,selectedId:string|null,hoveredId:string|null,cssWidth:number){const ctx=canvas.getContext('2d');if(!ctx)return;ctx.clearRect(0,0,canvas.width,canvas.height);const scale=project.size.width/Math.max(1,cssWidth);
 const draw=(id:string,selected:boolean)=>{const quad=layerQuad(project,state,id),node=project.nodes.find(n=>n.id===id);if(!quad||!node)return;ctx.save();ctx.strokeStyle=selected?'#ffae79':'#c9f7eb';ctx.lineWidth=(selected?2:1.5)*scale;ctx.setLineDash(selected?[]:[5*scale,4*scale]);ctx.beginPath();quad.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.shadowColor='#000b';ctx.shadowBlur=3*scale;ctx.stroke();ctx.shadowBlur=0;
  if(selected){ctx.fillStyle='#fff9ee';for(const p of quad){ctx.fillRect(p.x-4*scale,p.y-4*scale,8*scale,8*scale);ctx.strokeRect(p.x-4*scale,p.y-4*scale,8*scale,8*scale);}const label=node.name.slice(0,35);ctx.font=`600 ${11*scale}px Arial`;const width=ctx.measureText(label).width+14*scale,height=23*scale,x=Math.max(0,Math.min(canvas.width-width,Math.min(...quad.map(p=>p.x)))),y=Math.max(0,Math.min(canvas.height-height,Math.min(...quad.map(p=>p.y))-height-5*scale));ctx.fillStyle='#ffcfac';ctx.fillRect(x,y,width,height);ctx.fillStyle='#2b3c34';ctx.textBaseline='middle';ctx.fillText(label,x+7*scale,y+height/2);}
  ctx.restore();};if(hoveredId&&hoveredId!==selectedId)draw(hoveredId,false);if(selectedId)draw(selectedId,true);
}
