import {ui} from './i18n.ts';import {useInterfaceLocale} from './useInterfaceLocale.ts';import {layerDescription} from './layerLabels.ts';
import {useEffect,useRef} from 'react';import type {Project,SceneNode} from '../../domain/schema.ts';import {evaluateFrame,type FrameState} from '../../render/evaluate.ts';import {renderFrame,type AssetBitmaps,type ThreeLayerRenderer} from '../../render/renderFrame.ts';import {layerQuad,subtreeIds} from '../../domain/layers.ts';
export function LayerPreview({project,node,state,bitmaps,threeLayer,playing}:{project:Project;node:SceneNode;state:FrameState;bitmaps:AssetBitmaps;threeLayer?:ThreeLayerRenderer;playing:boolean}){
 const locale=useInterfaceLocale(),ref=useRef<HTMLCanvasElement|null>(null),visible=!!layerQuad(project,state,node.id);
 useEffect(()=>{if(playing||!ref.current)return;let cancelled=false;const canvas=ref.current,ctx=canvas.getContext('2d');if(!ctx)return;const draw=()=>{if(cancelled)return;ctx.clearRect(0,0,canvas.width,canvas.height);const points=layerQuad(project,state,node.id);if(!points)return;
  const ids=subtreeIds(project,node.id),off=document.createElement('canvas');off.width=project.size.width;off.height=project.size.height;const oc=off.getContext('2d');if(!oc)return;
  try{renderFrame({...state,items:state.items.filter(i=>ids.has(i.node.id))},{ctx:oc,project,bitmaps,threeLayer,transitions:false});const left=Math.max(0,Math.min(...points.map(p=>p.x))-20),top=Math.max(0,Math.min(...points.map(p=>p.y))-20),right=Math.min(off.width,Math.max(...points.map(p=>p.x))+20),bottom=Math.min(off.height,Math.max(...points.map(p=>p.y))+20),w=right-left,h=bottom-top;if(w<=0||h<=0)return;const scale=Math.min(canvas.width/w,canvas.height/h);ctx.drawImage(off,left,top,w,h,(canvas.width-w*scale)/2,(canvas.height-h*scale)/2,w*scale,h*scale);
  }finally{renderFrame(evaluateFrame(project,state.frame),{ctx:oc,project,bitmaps,threeLayer,transitions:false});off.width=off.height=1;}};
  if(threeLayer?.prepare)void threeLayer.prepare(project).then(draw).catch(()=>{if(cancelled)return;ctx.clearRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#b58a6c';ctx.font='12px Arial';ctx.fillText(ui('Модель недоступна'),12,24);});else draw();return()=>{cancelled=true};
 },[project,node,state,bitmaps,threeLayer,playing,locale]);
 return <div className="layer-preview"><canvas ref={ref} width={260} height={112} aria-label={ui('Миниатюра выбранного слоя')}/>{!visible&&<span>{ui('Не виден на этом кадре')}</span>}<small>{playing?ui('Миниатюра на паузе'):ui('Кадр')+' '+state.frame} · {layerDescription(project,node)}</small></div>;
}
