import {ui} from './i18n.ts';
import { useEffect, useState } from 'react';
import type { Project, SceneNode } from '../../domain/schema.ts';
import type { Operation } from '../../domain/operations.ts';
import { keyAt, keyEditReason, transformAtFrame } from '../../domain/animation.ts';
export function KeyframePanel({ project, node, frame, recording, busy, onRecording, onSeek, onAction }: {
    project: Project;
    node: SceneNode | null;
    frame: number;
    recording: boolean;
    busy: boolean;
    onRecording: (value: boolean) => void;
    onSeek: (frame: number) => void;
    onAction: (label: string, ops: Operation[], revision?: number) => Promise<boolean>;
}) {
    const [folded, setFolded] = useState(() => window.innerWidth <= 760);
    useEffect(() => { const media = matchMedia('(max-width:760px)'), adapt = () => setFolded(media.matches); media.addEventListener('change', adapt); return () => media.removeEventListener('change', adapt); }, []);
    const keys = [...(node?.transformKeys ?? [])].sort((a, b) => a.frame - b.frame), scene = project.sequences.find(s => s.id === node?.sequenceId), inside = !!scene && frame >= scene.fromFrame && frame < scene.toFrame, current = keys.find(k => k.frame === frame), reason = node ? keyEditReason(project, node.id) : ui("Выбери слой."), blocked = busy || !node || !!reason || !inside, previous = keys.filter(k => k.frame < frame).at(-1), next = keys.find(k => k.frame > frame), mode = recording || keys.length > 0;
    async function save() { if (blocked || !node)
        return; onRecording(true); await onAction(ui("Поставить ключ:") + " " + node.name, [{ op: 'setNodeKey', targetId: node.id, key: keyAt(node, frame) }], project.revision); }
    async function clear() { if (blocked || !node)
        return; if (await onAction(ui("Убрать анимацию:") + " " + node.name, [{ op: 'clearNodeKeys', targetId: node.id, frame }], project.revision))
        onRecording(false); }
    return <section className={'keyframe-panel ' + (mode ? 'recording' : '')} aria-label={ui("Ключи анимации")} data-folded={folded}><button className="keyframe-fold" aria-label={ui("Показать настройки анимации")} aria-expanded={!folded} onClick={() => setFolded(v => !v)}><span>{ui("Анимация")}</span><small>{keys.length ? keys.length + (" " + ui("ключей")) : ui("Без ключей")}</small><b>{folded ? '+' : '−'}</b></button><div className="keyframe-content"><div className="keyframe-controls"><label className="key-record" title={keys.length ? ui("У слоя уже есть анимация: изменения записываются в ключи. «Убрать анимацию» сохранит текущую позу.") : ui("Включи, чтобы перемещение и размер записывались на выбранном кадре.")}><input aria-label={ui("Записывать ключи анимации")} type="checkbox" checked={mode} disabled={busy || !node || !!reason || !!keys.length} onChange={e => onRecording(e.target.checked)}/><span>{ui("Ключи")}</span><small>{keys.length || '—'}</small></label><span className="key-object-name" title={node?.name}>{node?.name ?? ui("Выбери объект")}</span><div className="keyframe-actions"><button className="key-step" aria-label={ui("Предыдущий ключ объекта")} disabled={busy || !previous} onClick={() => previous && onSeek(previous.frame)}>‹</button><button className="key-save" aria-label={ui("Сохранить ключ на текущем кадре")} disabled={blocked} title={reason || ui("Записать текущие положение и размер")} onClick={() => void save()}>◆ {current ? ui("Обновить") : ui("Поставить ключ")}</button><button className="key-step" aria-label={ui("Следующий ключ объекта")} disabled={busy || !next} onClick={() => next && onSeek(next.frame)}>›</button><button className="key-delete" aria-label={ui("Удалить ключ на текущем кадре")} disabled={blocked || !current} title={ui("Удалить ключ · можно отменить")} onClick={() => node && void onAction(ui("Удалить ключ"), [{ op: 'removeNodeKey', targetId: node.id, frame }], project.revision)}>−◆</button><select aria-label={ui("Движение после ключа")} title={ui("Движение от этого ключа до следующего")} disabled={blocked || !current} value={current?.easing ?? 'smooth'} onChange={e => node && current && void onAction(ui("Изменить интерполяцию ключа"), [{ op: 'setNodeKey', targetId: node.id, key: { ...current, easing: e.target.value as 'smooth' | 'linear' | 'hold' } }], project.revision)}><option value="smooth">{ui("Плавно")}</option><option value="linear">{ui("Равномерно")}</option><option value="hold">{ui("Без перехода")}</option></select>{keys.length > 0 && <button className="key-clear" aria-label={ui("Убрать анимацию объекта")} title={ui("Оставить текущую позу без ключей · можно отменить")} disabled={blocked} onClick={() => void clear()}>{ui("Убрать анимацию")}</button>}</div></div>
 {scene && <div className="keyframe-lane-wrap"><small>{scene.fromFrame}</small><div className="keyframe-lane" aria-label={ui("Ключи выбранного объекта")}><i className="keyframe-playhead" style={{ left: Math.max(0, Math.min(100, (frame - scene.fromFrame) / Math.max(1, scene.toFrame - scene.fromFrame - 1) * 100)) + '%' }}/>{keys.map(k => <button key={k.frame} data-key-frame={k.frame} className={'keyframe-marker ' + (k.frame === frame ? 'current' : '')} style={{ left: (k.frame - scene.fromFrame) / Math.max(1, scene.toFrame - scene.fromFrame - 1) * 100 + '%' }} aria-label={ui("Ключ объекта на кадре") + " " + k.frame} title={ui("Кадр") + " " + k.frame + ' · ' + ({ smooth: ui("плавно"), linear: ui("равномерно"), hold: ui("без перехода") }[k.easing])} disabled={busy} onClick={() => onSeek(k.frame)}>◆</button>)}</div><small>{scene.toFrame - 1}</small><span className="keyframe-hint">{reason || (!inside ? ui("Кадр вне сцены объекта") : mode ? ui("Кадр → поза → следующий кадр → новая поза") : ui("Весь слой · включи ключи для анимации"))}</span></div>}
 </div></section>;
}
