import type{Project,SceneNode,TextNode}from'./schema.ts';import type{Operation}from'./operations.ts';
export type TemplateSummary={id:string;version:number;name:string;description:string;category:string;accent:string;durationSeconds:number;size:{width:number;height:number};previewFrame:number;projectSha256:string;attribution:string};
export type TemplateDetail={summary:TemplateSummary;project:Project};
export type ContentSlot={id:string;label:string;kind:'text'|'image';nodes:SceneNode[];maxLength:number;frame:number};
export function templateSlots(project:Project):ContentSlot[]{const slots=new Map<string,ContentSlot>();for(const n of project.nodes){const id=n.metadata?.slot;if(typeof id!=='string'||!['text','image'].includes(n.kind))continue;const slot=slots.get(id);if(slot){if(slot.kind!==n.kind)continue;slot.nodes.push(n)}else slots.set(id,{id,label:String(n.metadata?.slotLabel??n.name),kind:n.kind as'text'|'image',nodes:[n],maxLength:Math.max(1,Math.min(1000,Number(n.metadata?.slotMax??120))),frame:project.sequences.find(s=>s.id===n.sequenceId)?.fromFrame??0});}return[...slots.values()]}
export function templateName(project:Project){return project.nodes.find(n=>typeof n.metadata?.templateName==='string')?.metadata?.templateName as string|undefined}
export function templateTextOperations(project:Project,values:Record<string,string>,measure?:(text:string,font:string,size:number)=>number):Operation[]{const ops:Operation[]=[];for(const slot of templateSlots(project).filter(s=>s.kind==='text')){const value=values[slot.id];if(value===undefined)continue;if(!value.trim()||value.length>slot.maxLength||value.split('\n').length>3)throw Error(slot.label+': от1 до'+slot.maxLength+'символов, не больше3 строк.');for(const raw of slot.nodes){const n=raw as TextNode;if(n.text===value)continue;const top=Number(n.metadata?.slotFontSize??n.fontSize),lines=value.split('\n'),width=Math.max(...lines.map(line=>measure?measure(line,n.fontFamily,top):line.length*top*.72)),fontSize=Math.max(6,Math.min(top,top*(n.geometry.width-3)/Math.max(1,width),n.geometry.height/(lines.length*n.lineHeight)));ops.push({op:'updateNode',targetId:n.id,values:{text:value,fontSize}})}}return ops}
export function templateImageOperations(project:Project,slotId:string,assetId:string):Operation[]{const slot=templateSlots(project).find(s=>s.id===slotId&&s.kind==='image');if(!slot)throw Error('Поле изображения не найдено.');if(!project.assets.some(a=>a.id===assetId&&a.mime.startsWith('image/')))throw Error('Выберите изображение проекта.');return slot.nodes.map(n=>({op:'updateNode' as const,targetId:n.id,values:{assetId}}))}
