import type {Project,SceneNode,Scene3dNode} from './schema.ts';import type {Operation} from './operations.ts';import {newId} from './ids.ts';import {evaluateFrame,type FrameState} from '../render/evaluate.ts';import {selectionQuad} from '../render/renderFrame.ts';import {applyMatrix,invert} from './matrix.ts';
export type LayerKind='text'|'rect'|'ellipse'|'group'|'scene3d'|'image';
export const PRESET_LABELS:Record<Scene3dNode['preset'],string>={'imported-model':'Импортированная модель','gear-cluster':'Шестерни','logo-monolith':'Монолит','neon-reactor':'Неоновый реактор','ribbon-tunnel':'Световой тоннель','anatomy-device':'Разборное устройство'};
export function subtreeIds(project:Project,id:string){const ids=new Set([id]);for(let n=0;n<project.nodes.length;n++){let grew=false;for(const node of project.nodes)if(node.parentId&&ids.has(node.parentId)&&!ids.has(node.id)){ids.add(node.id);grew=true;}if(!grew)break;}return ids;}
export function layerLockReason(project:Project,id:string,includeSelf=true){let n=project.nodes.find(n=>n.id===id);if(!n)return'Слой удалён.';if(!includeSelf)n=n.parentId?project.nodes.find(p=>p.id===n!.parentId):undefined;while(n){if(n.locked)return'Заблокирован слой «'+n.name+'».';n=n.parentId?project.nodes.find(p=>p.id===n!.parentId):undefined;}return'';}
export function deleteLayerOperations(project:Project,id:string):Operation[]{const ids=subtreeIds(project,id),reason=layerLockReason(project,id);if(reason)throw Error(reason);if(project.nodes.some(n=>ids.has(n.id)&&n.locked))throw Error('В группе есть заблокированные слои. Сначала разблокируй их.');return[{op:'deleteNode',targetId:id,recursive:true}];}
export function moveLayerOperation(project:Project,id:string,direction:'front'|'back'):Operation[]{const node=project.nodes.find(n=>n.id===id);if(!node)throw Error('Слой удалён.');const reason=layerLockReason(project,id);if(reason)throw Error(reason);const siblings=project.nodes.filter(n=>n.parentId===node.parentId&&n.sequenceId===node.sequenceId),index=siblings.findIndex(n=>n.id===id),next=index+(direction==='front'?1:-1);return next<0||next>=siblings.length?[]:[{op:'reorderNode',targetId:id,index:next}];}
export function createLayer(project:Project,input:{kind:LayerKind;sequenceId:string;parentId:string|null;frame:number;name:string;text?:string;color?:string;assetId?:string;preset?:Scene3dNode['preset']},id=newId('layer')):SceneNode{
 const scene=project.sequences.find(s=>s.id===input.sequenceId);if(!scene)throw Error('Выбери существующую сцену.');const parent=input.parentId?project.nodes.find(n=>n.id===input.parentId):null;
 if(input.parentId&&(!parent||parent.kind!=='group'||parent.sequenceId!==scene.id))throw Error('Группа должна принадлежать выбранной сцене.');if(parent){const reason=layerLockReason(project,parent.id);if(reason)throw Error(reason);}
 const camera=evaluateFrame(project,Math.max(scene.fromFrame,Math.min(scene.toFrame-1,input.frame))).camera;
 const width=input.kind==='group'?project.size.width:input.kind==='text'?Math.min(800,project.size.width*.65):input.kind==='scene3d'?520:input.kind==='image'?480:input.kind==='ellipse'?260:320;
 const height=input.kind==='group'?project.size.height:input.kind==='text'?140:input.kind==='scene3d'?520:input.kind==='image'?320:input.kind==='ellipse'?260:220;
 const cx=parent?parent.geometry.width/2:camera.cx,cy=parent?parent.geometry.height/2:camera.cy;
 const base={id,name:input.name.trim()||'Новый слой',parentId:parent?.id??null,sequenceId:scene.id,geometry:{width,height},transform:{x:cx-width/2,y:cy-height/2,rotation:0,scaleX:1,scaleY:1,opacity:1,pivotX:0,pivotY:0},visible:true,locked:false};
 const color=input.color??'#72e4c3';
 if(input.kind==='text')return{...base,kind:'text',text:input.text??'Новая идея',fontFamily:'Arial',fontSize:72,color,align:'center',lineHeight:1.2};
 if(input.kind==='rect'||input.kind==='ellipse')return{...base,kind:'shape',shape:input.kind==='rect'?'rect':'ellipse',fill:color,fillOpacity:1};
 if(input.kind==='group')return{...base,kind:'group'};
 if(input.kind==='scene3d')return{...base,kind:'scene3d',adapter:'three',preset:input.preset??'neon-reactor',spin:.3,explode:0};
 const asset=project.assets.find(a=>a.id===input.assetId&&a.mime.startsWith('image/'));if(!asset)throw Error('Выбери изображение из проекта.');return{...base,kind:'image',assetId:asset.id,fit:'contain'};
}
export function layerDescription(project:Project,node:SceneNode){if(node.kind==='text')return node.text.replace(/\s+/g,' ').trim()||'Пустой текст';if(node.kind==='shape')return(node.shape==='ellipse'?'Круг / эллипс':'Прямоугольник')+' · '+node.fill;if(node.kind==='image')return project.assets.find(a=>a.id===node.assetId)?.title??'Изображение';if(node.kind==='scene3d')return'3D · '+PRESET_LABELS[node.preset];return'Группа · '+project.nodes.filter(n=>n.parentId===node.id).length+' слоёв';}
export function layerQuad(project:Project,state:FrameState,id:string){const node=project.nodes.find(n=>n.id===id);if(node?.kind!=='group')return selectionQuad(state,id);const item=state.items.find(i=>i.node.id===id);if(!item)return null;const ids=subtreeIds(project,id),points=state.items.filter(i=>ids.has(i.node.id)&&i.node.kind!=='group').flatMap(i=>selectionQuad(state,i.node.id)??[]);if(!points.length)return selectionQuad(state,id);let inverse;try{inverse=invert(item.screen)}catch{return null}const local=points.map(p=>applyMatrix(inverse,p.x,p.y)),x=Math.min(...local.map(p=>p.x)),y=Math.min(...local.map(p=>p.y)),right=Math.max(...local.map(p=>p.x)),bottom=Math.max(...local.map(p=>p.y));return[{x,y},{x:right,y},{x:right,y:bottom},{x,y:bottom}].map(p=>applyMatrix(item.screen,p.x,p.y));}
/** List is front-to-back; the stored sibling index is back-to-front. No reparenting. */
export function dropLayerOperations(project:Project,id:string,targetId:string,edge:'before'|'after'):Operation[]{const node=project.nodes.find(n=>n.id===id),target=project.nodes.find(n=>n.id===targetId);if(!node||!target)throw Error('Слой удалён.');const reason=layerLockReason(project,id);if(reason)throw Error(reason);if(node.parentId!==target.parentId||node.sequenceId!==target.sequenceId)throw Error('Перетаскивай между слоями одной группы и сцены.');if(id===targetId)return[];const siblings=project.nodes.filter(n=>n.parentId===node.parentId&&n.sequenceId===node.sequenceId),front=[...siblings].reverse().filter(n=>n.id!==id),at=front.findIndex(n=>n.id===targetId)+(edge==='after'?1:0);front.splice(at,0,node);const index=front.length-1-at;return siblings.findIndex(n=>n.id===id)===index?[]:[{op:'reorderNode',targetId:id,index}];}
export function layerViewFrame(project:Project,id:string,current:number){const node=project.nodes.find(n=>n.id===id),scene=project.sequences.find(s=>s.id===node?.sequenceId);if(!node||!scene)return current;const candidates=[current,Math.floor((scene.fromFrame+scene.toFrame-1)/2),...Array.from({length:17},(_,i)=>scene.fromFrame+Math.floor((scene.toFrame-scene.fromFrame-1)*i/16))];
 for(const frame of candidates){if(frame<scene.fromFrame||frame>=scene.toFrame)continue;const state=evaluateFrame(project,frame),quad=layerQuad(project,state,id);if(quad&&Math.max(...quad.map(p=>p.x))>=0&&Math.min(...quad.map(p=>p.x))<=project.size.width&&Math.max(...quad.map(p=>p.y))>=0&&Math.min(...quad.map(p=>p.y))<=project.size.height)return frame;}return Math.floor((scene.fromFrame+scene.toFrame-1)/2);
}
