import type {Project,SceneNode} from '../../domain/schema.ts';import type {Operation} from '../../domain/operations.ts';import {createLayer,layerLockReason} from '../../domain/layers.ts';import {addEffectOperation} from '../catalog.ts';import type {ShaderDefinition,ShaderParams} from './library.ts';
export type ShaderPlacement={kind:ShaderDefinition['kind'];sceneId:string;nodeId:string|null;frame:number;durationFrames:number;speed:number;hue:number;mix:number;params:ShaderParams};
export function shaderOperations(project:Project,shader:ShaderDefinition,options:ShaderPlacement,id:string):{operations:Operation[];selectedId:string|null}{
 if(shader.kind==='transition')return{operations:[{op:'setSceneTransition',targetId:options.sceneId,transition:{shaderId:shader.id,durationFrames:options.durationFrames,params:options.params}}],selectedId:options.nodeId};
 if(shader.kind==='filter'){if(!options.nodeId)throw Error('Выбери объект для фильтра.');const node=project.nodes.find(n=>n.id===options.nodeId),scene=project.sequences.find(s=>s.id===node?.sequenceId);if(!node||!scene)throw Error('Объект удалён.');return{operations:[addEffectOperation(project,node.id,'shader-filter',{shaderId:shader.id,settings:JSON.stringify(options.params),mix:options.mix,speed:options.speed},scene.fromFrame,scene.toFrame,id)],selectedId:node.id};}
 const node=createLayer(project,{kind:'rect',sequenceId:options.sceneId,parentId:null,frame:options.frame,name:shader.name},id)as SceneNode&{kind:'shape'},cx=node.transform.x+node.geometry.width/2,cy=node.transform.y+node.geometry.height/2;node.geometry={...project.size};node.transform.x=cx-node.geometry.width/2;node.transform.y=cy-node.geometry.height/2;node.generator={shaderId:shader.id,params:options.params,speed:options.speed,hue:options.hue};
 const backgrounds=project.nodes.filter(n=>n.sequenceId===options.sceneId&&n.parentId===null&&n.kind==='shape'&&(/^(?:фон(?: сцены)?|background)$/i.test(n.name)||!!n.generator));for(const n of backgrounds.filter(n=>n.visible)){const reason=layerLockReason(project,n.id);if(reason)throw Error(reason);}
 return{operations:[...backgrounds.filter(n=>n.visible).map(n=>({op:'updateNode' as const,targetId:n.id,values:{visible:false}})),{op:'createNode',node},{op:'reorderNode',targetId:node.id,index:0}],selectedId:node.id};
}
