import {useHelpImageSet} from './helpImages.ts';
import {message} from './i18n.ts';
import {currentLocale} from './locale.ts';
import {ui} from './i18n.ts';
export function HelpGuide({ topic }: {
    topic: string;
}) {
    const illustrations=useHelpImageSet();
    const routes: Record<string, Array<{
        title: string;
        text: string;
        image?: string;
        alt?: string;
    }>> = {
        start: [{ title: ui("1. Откройте основу"), text: ui("На главной выберите «Шаблоны» или «Примеры». Сначала посмотрите ролик, затем создайте свою копию. Встроенные материалы доступны без сети."), image: 'templates.png', alt: ui("Галерея шаблонов Motivelium") }, { title: ui("2. Замените материалы"), text: ui("В проекте откройте «Материалы шаблона»: измените заголовки, выберите своё изображение и музыку. Остальные объекты доступны через «Слои»."), image: 'materials.png', alt: ui("Панель замены материалов шаблона") }, { title: ui("3. Поручите доработку ИИ"), text: ui("Настройки → ИИ: скопируйте конфигурацию MCP в своего ИИ-клиента. Профиль встроенного GLM для внешнего MCP не требуется. Оставьте студию открытой.") }, { title: ui("4. Сохраните результат"), text: ui("Проект сохраняется после применения изменения. «Экспорт → Видео MP4» создаёт ролик со звуком. «Файл → Скачать проект» сохраняет редактируемый проект со всеми ресурсами.") }],
        'ai-help': [{ title: ui("1. Подключите своего агента"), text: ui("Настройки → ИИ → «Скопировать конфигурацию». Добавьте локальный MCP-сервер в своём клиенте, переподключите его и скопируйте пробное поручение. У разных клиентов формат настройки отличается; команда и аргументы указаны в конфигурации."), image: 'mcp.png', alt: ui("Подключение MCP и пробное поручение в настройках") }, { title: ui("2. Рассмотрите примерку"), text: ui("Попросите ИИ подготовить черновик и показать реальные кадры, не применять автоматически. Посмотрите переходы и дайте конкретные замечания. У поручения есть общий бюджет: агент не должен дорабатывать бесконечно.") }, { title: ui("3. Примените или отмените"), text: ui("Применение изменяет проект; Ctrl+Z или кнопка «Отменить» возвращает прежнее состояние. Если параллельно изменили проект, черновик нужно пересчитать. Встроенные правки одного выбранного объекта через GLM доступны отдельно и требуют собственного профиля."), image: 'editor.png', alt: ui("Редактируемый проект, холст, слои и отмена в верхней панели") }],
        'media-help': [{ title: ui("Изображения, музыка и модели"), text: ui("В проекте откройте «Ресурсы». Загрузите PNG/JPEG/WebP или WAV/MP3, затем добавьте ресурс в сцену или на звуковую дорожку. Статическая модель добавляется из GLB; поддержка обычного MP4 как слоя пока не реализована."), image: 'resources.png', alt: ui("Панель ресурсов проекта и импорт материалов") }, { title: ui("Точное движение"), text: ui("Выберите объект на холсте или в «Слоях». Перемещайте его мышью, меняйте размер за углы. В ключах задайте разные положение и размер на нужных кадрах; между ними рассчитано плавное движение.") }, { title: ui("Звук и ритм"), text: ui("В панели звука настройте дорожки, громкость, обрезку, затухания и акценты. Сетка долей — подсказка: проверьте первую долю и темп на слух. Изображение и MP4 используют один звуковой микс.") }],
        'export-help': [{ title: ui("1. Проверьте компоненты"), text: ui("Настройки → Компоненты → «Проверить компоненты». Для MP4 нужны Chrome, FFmpeg с libx264/AAC и FFprobe. При необходимости укажите пути; после их сохранения перезапустите эту копию студии."), image: 'components.png', alt: ui("Проверка готовности компонентов для MP4") }, { title: ui("2. Получите MP4"), text: ui("Откройте «Экспорт → Видео MP4», запустите экспорт и дождитесь состояния «Видео готово». Скачайте файл и посмотрите изображение и звук. Не закрывайте студию во время задания."), image: 'export.png', alt: ui("Экспорт MP4 со статусом и готовым файлом") }, { title: ui("3. Перенесите редактируемый проект"), text: ui("«Файл → Скачать проект» сохраняет текущие сцены и их ресурсы в ZIP. На главной другой студии нажмите «Импортировать», проверьте состав и создайте копию. Старые проекты не перезаписываются. История отмен и готовые MP4 в архив проекта не входят.") }, { title: ui("Если не видны прежние проекты"), text: ui("Настройки → Хранилище показывает активную папку данных. Разные запуски могут использовать разные папки. Для переноса между папками на одном компьютере проверьте другое хранилище и перенесите нужный проект копией.") }]
    };
    return <section className="help-article illustrated-help">{(routes[topic] ?? routes.start)!.map(step => <article key={step.title}><h3>{step.title}</h3><p>{step.text}</p>{step.image && <figure><a href={'/help/' + illustrations + '/' + step.image} target="_blank" rel="noreferrer"><img src={'/help/' + illustrations + '/' + step.image} alt={step.alt} loading="lazy"/></a><figcaption>{step.alt} · {message(currentLocale(),illustrations.endsWith('/dark')?'appearance.dark':'appearance.light')}{ui(". Нажмите, чтобы рассмотреть.")}</figcaption></figure>}</article>)}</section>;
}
